public class UniqueTransaction {
    // Universal constant prefix
    public static final String PREFIX = "TX-";

    // Private static counter - shared lobby dispenser
    private static int sequenceCounter = 1000;

    // Final instance fields - permanent paper slip
    private final String transactionId;
    private final double amount;
    private final String description;
    private final long timestamp;

    // Private constructor forces usage of static factory method
    private UniqueTransaction(String id, double amount, String desc, long time) {
        this.transactionId = id;
        this.amount = amount;
        this.description = desc;
        this.timestamp = time;
    }

    // Static Factory Method
    public static UniqueTransaction create(double amount, String desc) {
        if (amount < 0.0) amount = 0.0;
        String cleanDesc = (desc != null && !desc.trim().isEmpty()) ? desc.trim() : "Unspecified";

        // Atomic sequence increment
        sequenceCounter++;
        String generatedId = PREFIX + sequenceCounter;
        long currentTime = System.currentTimeMillis();

        return new UniqueTransaction(generatedId, amount, cleanDesc, currentTime);
    }

    // Getters for final fields (NO SETTERS!)
    public String getTransactionId() { return transactionId; }
    public double getAmount() { return amount; }
    public String getDescription() { return description; }
    public long getTimestamp() { return timestamp; }

    // Static query for system volume
    public static int getTotalTransactionsIssued() {
        return sequenceCounter - 1000;
    }

    public void printReceipt() {
        System.out.println("[" + transactionId + "] $" + amount + " - " + description);
    }
}

public class Main {
    public static void main(String[] args) {
        UniqueTransaction t1 = UniqueTransaction.create(120.50, "Cloud Hosting");
        UniqueTransaction t2 = UniqueTransaction.create(45.00, "Domain Registration");
        UniqueTransaction t3 = UniqueTransaction.create(300.00, "SSL Certificate");

        t1.printReceipt();
        t2.printReceipt();
        t3.printReceipt();

        System.out.println("Total transactions issued: " + UniqueTransaction.getTotalTransactionsIssued());
    }
}

