class StudentRecordGenerator {
    private static int rollSeq = 202600;
    private static int count = 0;
    private final int rollNumber;
    private final String studentName;

    public StudentRecordGenerator(String name) {
        this.studentName = name;
        this.rollNumber = ++rollSeq;
        count++;
    }

    public int getRollNumber() { return rollNumber; }
    public String getStudentName() { return studentName; }
    public static int getTotalEnrolled() { return count; }
}

public class Main {
    public static void main(String[] args) {
        StudentRecordGenerator s1 = new StudentRecordGenerator("Amina");
        StudentRecordGenerator s2 = new StudentRecordGenerator("Bikram");
        System.out.println(s1.getStudentName() + ": " + s1.getRollNumber() + " | " + s2.getStudentName() + ": " + s2.getRollNumber() + " | Total: " + StudentRecordGenerator.getTotalEnrolled());
    }
}

class SystemEvent {
    public static final String SOURCE = "SYSTEM_BUS";
    private static int eventSeq = 0;

    private final String eventId;
    private final String eventType;
    private final long timestamp;

    private SystemEvent(String id, String type, long time) {
        this.eventId = id;
        this.eventType = type;
        this.timestamp = time;
    }

    public static SystemEvent createEvent(String type) {
        eventSeq++;
        String id = "EVT-" + eventSeq;
        return new SystemEvent(id, type, System.currentTimeMillis());
    }

    public String getEventId() { return eventId; }
    public String getEventType() { return eventType; }
}

public class Main {
    public static void main(String[] args) {
        SystemEvent e = SystemEvent.createEvent("USER_LOGIN");
        System.out.println("Event " + e.getEventId() + " [" + e.getEventType() + "] on " + SystemEvent.SOURCE);
    }
}

