class SecureTransactionEngine {
    private static int txCounter = 1000;
    private final String txId;
    private final double amount;

    private SecureTransactionEngine(String id, double amt) {
        this.txId = id;
        this.amount = amt;
    }

    public static SecureTransactionEngine create(double amount) {
        txCounter++;
        String prefix = amount > 10000.0 ? "TX-PRIORITY-" : "TX-STD-";
        return new SecureTransactionEngine(prefix + txCounter, amount);
    }

    public String getTxId() { return txId; }
}

public class Main {
    public static void main(String[] args) {
        SecureTransactionEngine t1 = SecureTransactionEngine.create(500.0);
        SecureTransactionEngine t2 = SecureTransactionEngine.create(25000.0);
        System.out.println("STD: " + t1.getTxId() + " | PRIORITY: " + t2.getTxId());
    }
}
